const FINAL_LOCAL = {"tela":[1024,572],"jaula":{"base":[512,445],"largura":140,"sprite":[439,559],"aberta":[475,559],"deslocamentoAberta":-36},"gato":{"escala":0.14736842105263157,"dentro":[0.5,0.86],"livre":[600,400]},"cadeados":[{"id":"logica","regiao":"Raciocínio Lógico","cor":"verde","tinta":"#4ade80","fracao":[0.37,0.645]},{"id":"algebra","regiao":"Álgebra Inicial","cor":"azul","tinta":"#60a5fa","fracao":[0.63,0.665]},{"id":"geometria","regiao":"Geometria","cor":"roxo","tinta":"#a855f7","fracao":[0.36,0.8]},{"id":"operacoes","regiao":"Operações","cor":"laranja","tinta":"#fb923c","fracao":[0.63,0.8]}],"cadeadoAltura":22.105263157894736,"menina":{"altura":78,"entrada":[512,548],"parada":[370,395]},"barra":{"x":20,"y":508,"altura":36,"espaco":8},"portal":{"centro":[835,285],"largura":190,"redemoinho":0.54,"grausSegundo":50,"crescer":0.8,"velocidade":160,"distanciaGato":40,"encolher":0.6,"branco":0.5},"caminhoFinal":[600,380],"final":{"alturaGato":200,"estrelas":40,"confetes":40},"slides":[{"img":"assets/final/historia_1_chaves.webp","text":"As quatro chaves abriram todos os cadeados!"},{"img":"assets/final/historia_2_abraco.webp","text":"Você salvou o gato!"},{"img":"assets/final/historia_3_portal.png","text":"Um portal mágico apareceu para levar vocês para casa."},{"img":"assets/final/historia_4_entrada.png","text":"Hora de voltar para casa!"}],"encerramento":{"img":"assets/final/fim_quarto.png","title":"Parabéns!","subtitle":"Você salvou o gato e aprendeu muito!","button":"Jogar de novo"}};
let finalLoading;
window.loadFinal = () => finalLoading ||= (async()=>{
  let data=FINAL_LOCAL;
  if(window.location.protocol!=='file:'){
    const response=await fetch('data/final.json');if(!response.ok)throw Error('Falha ao abrir data/final.json');data=await response.json();
  }
  for(const src of ['js/final-logic.js','js/final-puzzle.js'])if(!document.querySelector(`script[src="${src}"]`))await new Promise((resolve,reject)=>{
    const script=document.createElement('script');script.src=src;script.onload=resolve;script.onerror=()=>{script.remove();reject(Error(`Falha ao carregar ${src}`));};document.head.appendChild(script);
  });
  await window.FinalPuzzle.prepare(data);return window.FinalPuzzle;
})().catch(error=>{finalLoading=null;throw error;});

// Registro único: abertura e pré-carga compartilham as Promises dos carregadores.
window.PuzzleScenes={logica:()=>window.loadMemoryMaze(),algebra:()=>window.loadAlgebra(),geometria:()=>window.loadGeometria(),operacoes:()=>window.loadOperacoes(),montanha:()=>window.loadFinal()};
let puzzlePreloadStarted=false;
window.preloadPuzzles=canLoad=>{
  if(puzzlePreloadStarted)return;puzzlePreloadStarted=true;
  const queue=Object.entries(window.PuzzleScenes);
  function next() {
    if(!queue.length)return;
    const run=()=>{
      if(!canLoad()){next();return;}
      const [id,load]=queue.shift(),now=()=>typeof performance!=='undefined'?performance.now():Date.now(),start=now();
      Promise.resolve().then(load).then(()=>console.info(`puzzle ${id} pronto em ${Math.round(now()-start)} ms`))
        .catch(error=>console.error(`[Pré-carga ${id}]`,error)).finally(next);
    };
    setTimeout(()=>window.requestIdleCallback?window.requestIdleCallback(run,{timeout:1000}):run(),300);
  }
  next();
};
